const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});
    const upstream = b.dependency("libxcrypt_upstream", .{});

    // Create the main library
    const lib = b.addLibrary(.{
        .name = "xcrypt",
        .root_module = b.createModule(.{
            .target = target,
            .optimize = optimize,
        }),
    });

    // Generate config.h using addConfigHeader - minimal config
    const config_header = b.addConfigHeader(
        .{
            .style = .blank,
            .include_path = "config.h",
        },
        .{
            // Minimal system headers
            .HAVE_SYS_TYPES_H = 1,
            .HAVE_UNISTD_H = 1,
            .HAVE_STRING_H = 1,
            .HAVE_STDLIB_H = 1,
            .HAVE_STDINT_H = 1,
            .HAVE_ERRNO_H = 1,
            .HAVE_LIMITS_H = 1,
            .HAVE_STDBOOL_H = 1,
            .HAVE_STDALIGN_H = 1,
            .HAVE_SYS_CDEFS_H = 1,
            .HAVE_SYS_CDEFS_THROW = 1,

            // Memory functions
            .HAVE_EXPLICIT_BZERO = null,
            .HAVE_EXPLICIT_MEMSET = null,
            .HAVE_MEMSET_S = null,

            // Randomness sources
            .HAVE_GETENTROPY = null,
            .HAVE_GETRANDOM = null,
            .HAVE_ARC4RANDOM_BUF = null,

            // Endianness
            .WORDS_BIGENDIAN = 0,
            .ENDIANNESS_IS_LITTLE = 1,
            .ENDIANNESS_IS_BIG = null,
            .ENDIANNESS_IS_PDP = null,

            // Build configuration - start minimal
            .ENABLE_FAILURE_TOKENS = 1,
            .ENABLE_OBSOLETE_API = 0,
            .ENABLE_OBSOLETE_API_ENOSYS = 1,

            // Enable all algorithms
            .INCLUDE_descrypt = 1,
            .INCLUDE_bigcrypt = 1,
            .INCLUDE_bsdicrypt = 1,
            .INCLUDE_md5crypt = 1,
            .INCLUDE_nt = 1,
            .INCLUDE_sunmd5 = 1,
            .INCLUDE_sha1crypt = 1,
            .INCLUDE_bcrypt = 1,
            .INCLUDE_bcrypt_a = 1,
            .INCLUDE_bcrypt_x = 1,
            .INCLUDE_bcrypt_y = 1,
            .INCLUDE_scrypt = 1,
            .INCLUDE_gost_yescrypt = 1,
            .INCLUDE_yescrypt = 1,
            .INCLUDE_sm3crypt = 1,
            .INCLUDE_sm3_yescrypt = 1,
            .INCLUDE_sha256crypt = 1,
            .INCLUDE_sha512crypt = 1,

            // Symbol versioning (disabled for static lib)
            .SYMVER_FLOOR = "",
            .SYMVER_CEILING = "",

            // Core functions
            .HAVE_FUNC_CRYPT = 1,
            .HAVE_FUNC_CRYPT_R = 1,
            .HAVE_FUNC_CRYPT_RN = 1,
            .HAVE_FUNC_CRYPT_GENSALT = 1,
            .HAVE_FUNC_CRYPT_GENSALT_R = 1,
            .HAVE_FUNC_CRYPT_GENSALT_RN = 1,
            .HAVE_FUNC_CRYPT_CHECKSALT = 1,
            .HAVE_FUNC_CRYPT_PREFERRED_METHOD = 1,

            // Function inclusion
            .INCLUDE_crypt = 1,
            .INCLUDE_crypt_r = 1,
            .INCLUDE_crypt_rn = 1,
            .INCLUDE_crypt_gensalt = 1,
            .INCLUDE_crypt_gensalt_rn = 1,
            .INCLUDE_crypt_gensalt_ra = 0,
            .INCLUDE_crypt_ra = 0,
            .INCLUDE_xcrypt = 0,
            .INCLUDE_xcrypt_r = 0,
            .INCLUDE_xcrypt_gensalt = 0,
            .INCLUDE_xcrypt_gensalt_r = 0,
            .INCLUDE_crypt_checksalt = 0,
            .INCLUDE_crypt_preferred_method = 0,

            // Compiler features
            .HAVE_STRONG_ALIAS = 1,
            .HAVE_STATIC_ASSERT_IN_ASSERT_H = 1,
            .HAVE__STATIC_ASSERT = 1,
            .HAVE_MAX_ALIGN_T = 1,

            // Package info
            .PACKAGE_NAME = "libxcrypt",
            .PACKAGE_VERSION = "4.5.0",
            .PACKAGE_STRING = "libxcrypt 4.5.0",
        },
    );
    lib.root_module.addConfigHeader(config_header);

    // Generate minimal headers for Zig static builds.
    const symver_header_contents =
        \\/* Generated by build.zig for Zig static builds */
        \\#ifndef _CRYPT_SYMBOL_VERS_H
        \\#define _CRYPT_SYMBOL_VERS_H 1
        \\#define SYMVER_crypt
        \\#define SYMVER_crypt_r
        \\#define SYMVER_crypt_rn
        \\#define SYMVER_crypt_ra
        \\#define SYMVER_crypt_gensalt
        \\#define SYMVER_crypt_gensalt_r
        \\#define SYMVER_crypt_gensalt_rn
        \\#define SYMVER_crypt_gensalt_ra
        \\#define SYMVER_crypt_checksalt
        \\#define SYMVER_crypt_preferred_method
        \\#define SYMVER_fcrypt
        \\#define SYMVER_xcrypt
        \\#define SYMVER_xcrypt_r
        \\#define SYMVER_xcrypt_gensalt
        \\#define SYMVER_xcrypt_gensalt_r
        \\#define SYMVER_encrypt
        \\#define SYMVER_encrypt_r
        \\#define SYMVER_setkey
        \\#define SYMVER_setkey_r
        \\#endif
    ;
    const crypt_h_contents =
        \\/* High-level libcrypt interfaces - Generated from crypt.h.in */
        \\#ifndef _CRYPT_H
        \\#define _CRYPT_H 1
        \\#ifdef __cplusplus
        \\extern "C" {
        \\#endif
        \\#define CRYPT_OUTPUT_SIZE 384
        \\#define CRYPT_MAX_PASSPHRASE_SIZE 512
        \\#define CRYPT_GENSALT_OUTPUT_SIZE 192
        \\extern char *crypt (const char *__phrase, const char *__setting)
        \\__attribute__((__nothrow__));
        \\#define CRYPT_DATA_RESERVED_SIZE 767
        \\#define CRYPT_DATA_INTERNAL_SIZE 30720
        \\struct crypt_data
        \\{
        \\  char output[CRYPT_OUTPUT_SIZE];
        \\  char setting[CRYPT_OUTPUT_SIZE];
        \\  char input[CRYPT_MAX_PASSPHRASE_SIZE];
        \\  char reserved[CRYPT_DATA_RESERVED_SIZE];
        \\  char initialized;
        \\  char internal[CRYPT_DATA_INTERNAL_SIZE];
        \\};
        \\extern char *crypt_r (const char *__phrase, const char *__setting,
        \\                      struct crypt_data *__restrict __data)
        \\__attribute__((__nothrow__));
        \\extern char *crypt_rn (const char *__phrase, const char *__setting,
        \\                       void *__data, int __size)
        \\__attribute__((__nothrow__));
        \\extern char *crypt_ra (const char *__phrase, const char *__setting,
        \\                       void **__data, int *__size)
        \\__attribute__((__nothrow__));
        \\extern char *crypt_gensalt (const char *__prefix, unsigned long __count,
        \\                            const char *__rbytes, int __nrbytes)
        \\__attribute__((__nothrow__));
        \\extern char *crypt_gensalt_rn (const char *__prefix, unsigned long __count,
        \\                               const char *__rbytes, int __nrbytes,
        \\                               char *__output, int __output_size)
        \\__attribute__((__nothrow__));
        \\extern char *crypt_gensalt_ra (const char *__prefix, unsigned long __count,
        \\                               const char *__rbytes, int __nrbytes)
        \\__attribute__((__nothrow__));
        \\extern int crypt_checksalt (const char *__setting);
        \\extern const char *crypt_preferred_method (void);
        \\#include <stdint.h>
        \\/* Raw scrypt KDF.  Defined in lib/alg-yescrypt-common.c as crypto_scrypt
        \\   and renamed to _crypt_crypto_scrypt by crypt-port.h to keep libxcrypt's
        \\   internal namespace clean; we re-expose the public name via the same
        \\   #define-then-extern pattern used by crypt-hashes.h.
        \\   N must be a power of 2 greater than 1; r * p < 2^30.
        \\   Returns 0 on success, -1 on error.  */
        \\#define crypto_scrypt _crypt_crypto_scrypt
        \\extern int crypto_scrypt (const uint8_t *__passwd, size_t __passwdlen,
        \\                          const uint8_t *__salt, size_t __saltlen,
        \\                          uint64_t __N, uint32_t __r, uint32_t __p,
        \\                          uint8_t *__buf, size_t __buflen);
        \\extern char *xcrypt (const char *__phrase, const char *__setting)
        \\__attribute__((__nothrow__));
        \\extern char *xcrypt_r (const char *__phrase, const char *__setting,
        \\                       struct crypt_data *__restrict __data)
        \\__attribute__((__nothrow__));
        \\extern char *xcrypt_gensalt (const char *__prefix, unsigned long __count,
        \\                             const char *__rbytes, int __nrbytes)
        \\__attribute__((__nothrow__));
        \\extern char *xcrypt_gensalt_r (const char *__prefix, unsigned long __count,
        \\                               const char *__rbytes, int __nrbytes,
        \\                               char *__output, int __output_size)
        \\__attribute__((__nothrow__));
        \\#ifdef __cplusplus
        \\}
        \\#endif
        \\#endif /* crypt.h */
    ;
    const generated_headers = b.addWriteFiles();
    _ = generated_headers.add("crypt-symbol-vers.h", symver_header_contents);
    const crypt_h = generated_headers.add("crypt.h", crypt_h_contents);

    // Add include paths
    lib.root_module.addIncludePath(generated_headers.getDirectory());
    lib.root_module.addIncludePath(b.path("."));
    lib.root_module.addIncludePath(upstream.path("lib"));
    lib.root_module.addIncludePath(upstream.path("."));

    // All algorithm sources
    const lib_sources = [_][]const u8{
        // Core algorithm files
        "lib/alg-des-tables.c",
        "lib/alg-des.c",
        "lib/alg-gost3411-2012-core.c",
        "lib/alg-gost3411-2012-hmac.c",
        "lib/alg-hmac-sha1.c",
        "lib/alg-md4.c",
        "lib/alg-md5.c",
        "lib/alg-sha1.c",
        "lib/alg-sha256.c",
        "lib/alg-sha512.c",
        "lib/alg-sm3-hmac.c",
        "lib/alg-sm3.c",
        "lib/alg-yescrypt-common.c",
        "lib/alg-yescrypt-opt.c",

        // Crypt implementations
        "lib/crypt-bcrypt.c",
        "lib/crypt-des-obsolete.c",
        "lib/crypt-des.c",
        "lib/crypt-gost-yescrypt.c",
        "lib/crypt-md5.c",
        "lib/crypt-nthash.c",
        "lib/crypt-pbkdf1-sha1.c",
        "lib/crypt-scrypt.c",
        "lib/crypt-sha256.c",
        "lib/crypt-sha512.c",
        "lib/crypt-sm3-yescrypt.c",
        "lib/crypt-sm3.c",
        "lib/crypt-sunmd5.c",
        "lib/crypt-yescrypt.c",

        // Core infrastructure
        "lib/crypt.c",
        "lib/crypt-static.c",
        "lib/crypt-gensalt-static.c",

        // Utilities
        "lib/util-base64.c",
        "lib/util-gensalt-sha.c",
        "lib/util-get-random-bytes.c",
        "lib/util-make-failure-token.c",
        "lib/util-xbzero.c",
        "lib/util-xstrcpy.c",
    };

    // Compile flags
    const cflags = [_][]const u8{
        "-std=gnu2x",
        "-D_DEFAULT_SOURCE",
        "-D_GNU_SOURCE",
        "-DHAVE_CONFIG_H=1",
        "-DIN_LIBCRYPT",
        "-fno-strict-aliasing",
        "-Wno-error",
    };

    for (lib_sources) |src| {
        lib.root_module.addCSourceFile(.{
            .file = upstream.path(src),
            .flags = &cflags,
        });
    }

    lib.root_module.link_libc = true;

    // Install library and headers
    b.installArtifact(lib);
    lib.installHeader(crypt_h, "crypt.h");
    lib.installHeader(config_header.getOutputFile(), "config.h");

    // Minimal test set
    const test_step = b.step("test", "Run minimal tests");

    const test_programs = [_]struct {
        name: []const u8,
        source: []const u8,
    }{
        .{ .name = "test-alg-sha256", .source = "test/alg-sha256.c" },
        .{ .name = "test-alg-sha512", .source = "test/alg-sha512.c" },
        // These tests need more infrastructure:
        // .{ .name = "test-crypt-badargs", .source = "test/crypt-badargs.c" },
        // .{ .name = "test-gensalt", .source = "test/gensalt.c" },
    };

    const test_cflags = [_][]const u8{
        "-std=gnu2x",
        "-D_DEFAULT_SOURCE",
        "-D_GNU_SOURCE",
        "-DHAVE_CONFIG_H=1",
        "-fno-strict-aliasing",
        "-Wno-error",
    };

    for (test_programs) |test_prog| {
        const test_exe = b.addExecutable(.{
            .name = test_prog.name,
            .root_module = b.createModule(.{
                .target = target,
                .optimize = optimize,
            }),
        });

        test_exe.root_module.addCSourceFile(.{
            .file = upstream.path(test_prog.source),
            .flags = &test_cflags,
        });

        test_exe.root_module.addIncludePath(generated_headers.getDirectory());
        test_exe.root_module.addIncludePath(b.path("."));
        test_exe.root_module.addIncludePath(upstream.path("lib"));
        test_exe.root_module.addIncludePath(upstream.path("test"));
        test_exe.root_module.addIncludePath(upstream.path("."));
        test_exe.root_module.addConfigHeader(config_header);

        test_exe.root_module.linkLibrary(lib);
        test_exe.root_module.link_libc = true;

        const run_test = b.addRunArtifact(test_exe);
        run_test.has_side_effects = true;
        test_step.dependOn(&run_test.step);
    }
}
